//! Bounded MIME import. Decodes data only; never renders HTML or resolves external content.
use crate::Result;use serde_json::{json,Value};use std::{collections::BTreeMap,path::Path};
const MAX:usize=16*1024*1024;
fn headers(bytes:&[u8])->Result<(BTreeMap<String,String>,&[u8])>{let end=[bytes.windows(4).position(|s|s==b"\r\n\r\n").map(|n|(n,4)),bytes.windows(2).position(|s|s==b"\n\n").map(|n|(n,2))].into_iter().flatten().min_by_key(|v|v.0).ok_or("Missing MIME header separator")?;if end.0>16384{return Err("MIME headers exceed16KiB".into())}let text=std::str::from_utf8(&bytes[..end.0]).map_err(|_|"Use encoded or UTF-8 MIME headers")?;let mut lines=Vec::<String>::new();for line in text.split('\n'){let line=line.strip_suffix('\r').unwrap_or(line);if line.len()>1000||line.chars().any(|c|c.is_control()&&c!='\t'){return Err("Invalid MIME header line".into())}if line.starts_with([' ','\t']){let last=lines.last_mut().ok_or("Orphan MIME folded header")?;last.push(' ');last.push_str(line.trim());}else{lines.push(line.into());}if lines.len()>100{return Err("Too many MIME headers".into())}}
 let mut out=BTreeMap::new();for line in lines{let(k,v)=line.split_once(':').ok_or("Invalid MIME header")?;if k.is_empty()||!k.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'){return Err("Invalid MIME header name".into())}let k=k.to_ascii_lowercase();if ["from","to","subject","content-type","content-disposition","content-transfer-encoding"].contains(&k.as_str())&&out.insert(k,v.trim().into()).is_some(){return Err("Ambiguous duplicate MIME header".into())}}Ok((out,&bytes[end.0+end.1..]))}
fn parameters(s:&str)->Result<(String,BTreeMap<String,String>)>{let mut parts=Vec::new();let(mut start,mut quote,mut escape)=(0,false,false);for(i,c)in s.char_indices(){if escape{escape=false;continue}if c=='\\'&&quote{escape=true}else if c=='"'{quote=!quote}else if c==';'&&!quote{parts.push(&s[start..i]);start=i+1;}}if quote||escape{return Err("Invalid quoted MIME parameter".into())}parts.push(&s[start..]);let kind=parts[0].trim().to_ascii_lowercase();let mut out=BTreeMap::new();for p in parts.into_iter().skip(1){let(k,v)=p.trim().split_once('=').ok_or("Invalid MIME parameter")?;let v=v.trim();let v=if v.starts_with('"'){let v=v.strip_prefix('"').and_then(|s|s.strip_suffix('"')).ok_or("Unclosed MIME parameter")?;let mut out=String::new();let mut chars=v.chars();while let Some(c)=chars.next(){out.push(if c=='\\'{chars.next().ok_or("Invalid MIME escape")?}else{c});}out}else{v.into()};let k=k.trim().to_ascii_lowercase();if k.is_empty()||v.len()>1024||v.chars().any(char::is_control)||out.insert(k,v).is_some(){return Err("Duplicate/oversized MIME parameter".into())}}Ok((kind,out))}
fn base64(s:&[u8])->Result<Vec<u8>>{let b:Vec<_>=s.iter().copied().filter(|b|!b.is_ascii_whitespace()).collect();if b.len()%4!=0||b.len()>MAX*2{return Err("Invalid MIME base64 length".into())}let mut out=Vec::new();for(i,c)in b.chunks(4).enumerate(){let last=i+1==b.len()/4;let val=|v:u8|->Result<u8>{match v{b'A'..=b'Z'=>Ok(v-b'A'),b'a'..=b'z'=>Ok(v-b'a'+26),b'0'..=b'9'=>Ok(v-b'0'+52),b'+'=>Ok(62),b'/'=>Ok(63),_=>Err("Invalid MIME base64".into())}};let a=val(c[0])?;let d=val(c[1])?;out.push(a<<2|d>>4);if c[2]==b'=' {if !last||c[3]!=b'='||d&15!=0{return Err("Invalid MIME base64 padding".into())}}else{let e=val(c[2])?;out.push(d<<4|e>>2);if c[3]==b'=' {if !last||e&3!=0{return Err("Invalid MIME base64 padding".into())}}else{out.push(e<<6|val(c[3])?);}}}Ok(out)}
fn qp(s:&[u8],word:bool)->Result<Vec<u8>>{let mut out=Vec::new();let mut i=0;while i<s.len(){if s[i]==b'=' {if s.get(i+1..i+3)==Some(b"\r\n"){i+=3;continue}if s.get(i+1)==Some(&b'\n'){i+=2;continue}let h=s.get(i+1..i+3).ok_or("Invalid quoted printable")?;let v=u8::from_str_radix(std::str::from_utf8(h).map_err(|_|"Invalid quoted printable")?,16).map_err(|_|"Invalid quoted printable")?;out.push(v);i+=3;}else{out.push(if word&&s[i]==b'_'{b' '}else{s[i]});i+=1;}}Ok(out)}
fn charset(bytes:Vec<u8>,name:&str)->Result<String>{match name.to_ascii_lowercase().as_str(){"utf-8"=>String::from_utf8(bytes).map_err(|_|"Invalid UTF-8 MIME text".into()),"us-ascii"=>{if !bytes.is_ascii(){return Err("Non-ASCII MIME text".into())}Ok(String::from_utf8(bytes).unwrap())},"iso-8859-1"|"latin1"=>Ok(bytes.into_iter().map(char::from).collect()),"windows-1252"=>{let table=[0x20ac,0,0x201a,0x192,0x201e,0x2026,0x2020,0x2021,0x2c6,0x2030,0x160,0x2039,0x152,0,0x17d,0,0,0x2018,0x2019,0x201c,0x201d,0x2022,0x2013,0x2014,0x2dc,0x2122,0x161,0x203a,0x153,0,0x17e,0x178];let mut out=String::new();for b in bytes{let n=if(128..160).contains(&b){table[(b-128)as usize]}else{b as u32};if n==0&&b!=0{return Err("Undefined Windows1252 character".into())}out.push(char::from_u32(n).ok_or("Invalid Windows1252 character")?);}Ok(out)},_=>Err("Unsupported MIME charset".into())}}

fn words(s:&str)->Result<String>{let mut rest=s;let mut out=String::new();while let Some(i)=rest.find("=?"){out.push_str(&rest[..i]);let end=rest[i+2..].find("?=").ok_or("Invalid encoded MIME word")?+i+2;let parts:Vec<_>=rest[i+2..end].split('?').collect();if parts.len()!=3{return Err("Invalid encoded MIME word".into())}let decoded=match parts[1].to_ascii_lowercase().as_str(){"b"=>base64(parts[2].as_bytes())?,"q"=>qp(parts[2].as_bytes(),true)?,_=>return Err("Unsupported encoded MIME word".into())};out.push_str(&charset(decoded,parts[0])?);rest=&rest[end+2..];let trimmed=rest.trim_start_matches([' ','\t']);if trimmed.starts_with("=?"){rest=trimmed;}}out.push_str(rest);if out.len()>2048||out.chars().any(char::is_control){return Err("Invalid decoded MIME header".into())}Ok(out)}
struct Parsed{text:String,attachments:Vec<(String,String,Vec<u8>)>,html:bool,parts:usize}
fn walk(bytes:&[u8],depth:usize,p:&mut Parsed)->Result<()>{if depth>8||p.parts>=32{return Err("MIME part/depth limit exceeded".into())}p.parts+=1;let(h,body)=headers(bytes)?;let(kind,params)=parameters(h.get("content-type").map(String::as_str).unwrap_or("text/plain"))?;let transfer=h.get("content-transfer-encoding").map(|s|s.to_ascii_lowercase()).unwrap_or("7bit".into());
 if kind.starts_with("multipart/"){if !["multipart/mixed","multipart/alternative","multipart/related"].contains(&kind.as_str())||!["7bit","8bit","binary"].contains(&transfer.as_str()){return Err("Unsupported multipart MIME type/encoding".into())}let boundary=params.get("boundary").filter(|s|!s.is_empty()&&s.len()<=70&&s.is_ascii()&&!s.chars().any(char::is_control)).ok_or("Invalid MIME boundary")?;let marker=format!("--{boundary}");let mut begin=None;let mut offset=0;let mut closed=false;let text_before=p.text.len();for line in body.split_inclusive(|b|*b==b'\n'){let stripped=line.strip_suffix(b"\n").unwrap_or(line).strip_suffix(b"\r").unwrap_or(line.strip_suffix(b"\n").unwrap_or(line));if stripped==marker.as_bytes()||stripped==format!("{marker}--").as_bytes(){if let Some(start)=begin{let part=body[start..offset].strip_suffix(b"\r\n").or_else(||body[start..offset].strip_suffix(b"\n")).unwrap_or(&body[start..offset]);let already=kind=="multipart/alternative"&&p.text.len()>text_before;let save=p.text.clone();walk(part,depth+1,p)?;if already{p.text=save;}}if stripped.ends_with(b"--")&&stripped!=marker.as_bytes(){closed=true;break}begin=Some(offset+line.len());}offset+=line.len();}if !closed{return Err("Unclosed MIME multipart".into())}return Ok(())}
 let decoded=match transfer.as_str(){"base64"=>base64(body)?,"quoted-printable"=>qp(body,false)?,"7bit"=>{if !body.is_ascii(){return Err("Non-ASCII7bit MIME body".into())}body.to_vec()},"8bit"|"binary"=>body.to_vec(),_=>return Err("Unsupported MIME transfer encoding".into())};if decoded.len()>10*1024*1024{return Err("MIME part exceeds10MiB".into())}let(disp,dparams)=parameters(h.get("content-disposition").map(String::as_str).unwrap_or("inline"))?;let filename=dparams.get("filename*").map(|v|{let v=v.strip_prefix("UTF-8''").or_else(||v.strip_prefix("utf-8''")).ok_or("Unsupported MIME filename charset")?;let mut b=Vec::new();let mut rest=v.as_bytes();while !rest.is_empty(){if rest[0]==b'%' {if rest.len()<3{return Err("Invalid MIME filename")};b.push(u8::from_str_radix(std::str::from_utf8(&rest[1..3]).map_err(|_|"Invalid MIME filename")?,16).map_err(|_|"Invalid MIME filename")?);rest=&rest[3..];}else{b.push(rest[0]);rest=&rest[1..];}}String::from_utf8(b).map_err(|_|"Invalid MIME filename")}).transpose()?.or_else(||dparams.get("filename").cloned()).or_else(||params.get("name").cloned());
 if disp=="attachment"||filename.is_some()||!["text/plain","text/html"].contains(&kind.as_str()){if p.attachments.len()>=3{return Err("At most3 MIME attachments".into())}let name=words(filename.as_deref().unwrap_or("attachment.bin"))?;if name.is_empty()||name.len()>128||name.contains(['/','\\'])||name=="."||name==".."{return Err("Unsafe MIME attachment filename".into())}if !kind.contains('/')||!kind.bytes().all(|b|b.is_ascii_alphanumeric()||b"/!#$&^_.+-".contains(&b)){return Err("Invalid MIME attachment type".into())}p.attachments.push((name,kind,decoded));}else if kind=="text/html"{p.html=true;}else{let text=charset(decoded,params.get("charset").map(String::as_str).unwrap_or("us-ascii"))?;if text.chars().any(|c|c.is_control()&&!matches!(c,'\n'|'\r'|'\t'))||p.text.len()+text.len()+usize::from(!p.text.is_empty())>8192{return Err("MIME plain body exceeds8KiB or contains unsafe controls".into())}if !p.text.is_empty(){p.text.push('\n')}p.text.push_str(&text);}Ok(())}
fn save_attachment(root:&Path,name:&str,mime:&str,bytes:&[u8])->Result<Value>{let created=crate::sdk_storage::service(root,"blobs.begin",&json!({"name":name,"mime":mime,"cache":true}))?;let id=created["id"].as_str().unwrap();let result=(||{for(n,chunk)in bytes.chunks(65536).enumerate(){let hex:String=chunk.iter().map(|b|format!("{b:02x}")).collect();crate::sdk_storage::service(root,"blobs.append",&json!({"id":id,"offset":n*65536,"hex":hex}))?;}crate::sdk_storage::service(root,"blobs.finish",&json!({"id":id}))})();if result.is_err(){let _=crate::sdk_storage::service(root,"blobs.delete",&json!({"id":id}));}result}
pub(crate) fn parse(root:&Path,args:&Value)->Result<Value>{let bytes=crate::sdk_storage::read_all(root,args["file"].as_str().ok_or("Choose a private MIME file")?,MAX as u64)?;let(h,_)=headers(&bytes)?;let mut p=Parsed{text:String::new(),attachments:Vec::new(),html:false,parts:0};walk(&bytes,0,&mut p)?;let mut out=json!({"subject":words(h.get("subject").map(String::as_str).unwrap_or(""))?,"from":words(h.get("from").map(String::as_str).unwrap_or(""))?,"to":words(h.get("to").map(String::as_str).unwrap_or(""))?,"text":p.text,"html_present":p.html,"html_rendered":false,"attachments":[]});let mut ids=Vec::new();for(name,mime,bytes)in p.attachments{match save_attachment(root,&name,&mime,&bytes){Ok(f)=>{ids.push(f["id"].as_str().unwrap().to_string());out["attachments"].as_array_mut().unwrap().push(f);},Err(e)=>{for id in ids{let _=crate::sdk_storage::service(root,"blobs.delete",&json!({"id":id}));}return Err(e)}}}Ok(out)}
#[cfg(test)]mod tests{use super::*;#[test]fn wrap_mime_decodes_multipart_and_never_renders_html(){let d=tempfile::tempdir().unwrap();let raw=b"Subject: =?UTF-8?Q?caf=C3=A9?=\r\nContent-Type: multipart/mixed; boundary=part\r\n\r\n--part\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Transfer-Encoding: quoted-printable\r\n\r\nHello=20world\r\n--part\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment; filename=demo.bin\r\nContent-Transfer-Encoding: base64\r\n\r\nAP+A\r\n--part--\r\n";let f=crate::sdk_storage::save_bytes(d.path(),"mail.eml","message/rfc822",raw).unwrap();let v=parse(d.path(),&json!({"file":f["id"]})).unwrap();assert_eq!(v["subject"],"café");assert_eq!(v["attachments"][0]["cache"],true);assert_eq!(v["text"],"Hello world");assert_eq!(crate::sdk_storage::read_all(d.path(),v["attachments"][0]["id"].as_str().unwrap(),10).unwrap(),vec![0,255,128]);}
#[test]fn wrap_mime_rejects_ambiguous_paths_padding_and_depth(){assert!(base64(b"AB==").is_err());assert!(headers(b"Subject: a\r\nSubject: b\r\n\r\nx").is_err());let mut p=Parsed{text:String::new(),attachments:vec![],html:false,parts:0};assert!(walk(b"Content-Type: application/pdf\r\nContent-Disposition: attachment; filename=../x\r\n\r\na",0,&mut p).is_err());assert!(walk(b"Content-Type: multipart/mixed; boundary=x\r\n\r\n--x\r\na",0,&mut p).is_err());assert!(walk(b"\r\n\r\na",9,&mut p).is_err());}}
